import {tests} from './model.mjs';
export const levels={support:{name:'Con apoyo',help:'Orientación visible y 3–4 opciones; todas las alternativas útiles siguen disponibles.'},independent:{name:'Autónomo',help:'Hasta 5 opciones, sin orientación inicial. Pistas disponibles.'},challenge:{name:'Desafío',help:'7 opciones. La pista se desbloquea después de una elección no prioritaria.'}};
export function progressByTest(records){return Object.keys(tests).map(id=>{const ordered=records.slice().sort((a,b)=>String(a.date).localeCompare(String(b.date)));const events=review=>ordered.filter(r=>!!r.reviewOf===review).flatMap(r=>r.log.filter(e=>e.choice===id));const summarize=list=>({n:list.length,good:list.filter(e=>e.correct).length,percent:list.length?Math.round(100*list.filter(e=>e.correct).length/list.length):null});return {id,first:summarize(events(false).slice(0,5)),review:summarize(events(true).slice(-5))};});}
export function difficulty(records,id=null){const relevant=records.filter(r=>r.status==='complete'&&(!id||r.reviewTest===id||r.log.some(e=>e.choice===id))).slice().sort((a,b)=>String(a.date).localeCompare(String(b.date))).slice(-3);const clean=r=>r.hints===0&&r.log.length&&r.log.every(e=>e.correct);const streak=relevant.slice().reverse().findIndex(r=>!clean(r));const count=streak<0?relevant.length:streak;return {level:count>=3?'challenge':count>=2?'independent':'support',count,sessions:relevant.length};}
export function choiceOptions(g,recommended){const all=Object.keys(tests),limit=g.level==='challenge'?7:g.level==='independent'?5:3;return [...new Set([...recommended,...all.filter(id=>!recommended.includes(id))])].slice(0,Math.max(limit,recommended.length+1)).sort((a,b)=>all.indexOf(a)-all.indexOf(b));}
export const canHint=g=>g.phase==='question'&&!g.hinted&&(g.level!=='challenge'||g.wrong.length>0);
